 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            out.setdefault(color, []).append(cells)
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    groups = _components(grid)
    pieces = []
    for color, comps in groups.items():
        if len(comps) != 2:
            raise ValueError('expected two components per color')
        small, large = sorted(comps, key=len)
        pieces.append((color, small, large))
    # Put the color whose larger source object is farther left in the left lane.
    pieces.sort(key=lambda p: min(c for r, c in p[2]))
    lane_widths = []
    for color, small, large in pieces:
        lane_widths.append(max(max(c for r, c in obj) - min(c for r, c in obj) + 1
                                for obj in (small, large)))
    anchors = []
    x = 0
    for width in lane_widths:
        anchors.append(x)
        x += width + 1
    max_large_h = max(max(r for r, c in large) - min(r for r, c in large) + 1
                      for _, _, large in pieces)
    large_top = h - max_large_h
    small_bottom = large_top - 2
    result = [[0] * w for _ in range(h)]
    for (color, small, large), anchor in zip(pieces, anchors):
        for obj, top in ((small, small_bottom - (max(r for r, c in small) - min(r for r, c in small))),
                         (large, large_top)):
            min_r = min(r for r, c in obj)
            min_c = min(c for r, c in obj)
            for r, c in obj:
                rr = top + r - min_r
                cc = anchor + c - min_c
                result[rr][cc] = color
    return result
